solution.Inspect.java:
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Inspect {
    public static List<String> getters(Class<?> type) {
        List<String> names = new ArrayList<>();
        for (Method m : type.getMethods()) {
            String n = m.getName();
            if (m.getParameterCount() != 0 || m.getReturnType() == void.class || n.equals("getClass")) continue;
            boolean getter = n.startsWith("get") && n.length() > 3;
            boolean isser = n.startsWith("is") && n.length() > 2 && m.getReturnType() == boolean.class;
            if (getter || isser) names.add(n);
        }
        Collections.sort(names);
        return names;
    }
}

unitTests:
test("finds the getters", () -> {
    checkEq(Inspect.getters(Fixtures.Person.class), java.util.List.of("getAge", "getName", "isActive"));
});

test("works on library classes", () -> {
    check(Inspect.getters(String.class).contains("isEmpty"), "String.isEmpty is a boolean getter");
    check(!Inspect.getters(Object.class).contains("getClass"), "getClass should be left out");
});

